    "type": "git",
    "url": "git+https://github.com/AeonDave/opencode-background-agents.git"
  },
  "license": "MIT",
  "type": "module",
  "main": "src/plugin/background-agents.ts",
  "exports": {
    ".": "./src/plugin/background-agents.ts"
